import { ViewTransition } from 'react'
import type { Metadata } from 'next'
import './globals.css'

export const metadata: Metadata = {
  title: 'Product Gallery',
  description: 'A simple product gallery',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>
        {/*
          Page-level slide. The class is keyed on the transition types the links
          pass to the router, so the direction follows the navigation rather than
          the URL: `forward` on the way into a product, `back` on the way out.

          `default: 'none'` deactivates this group for any other transition —
          notably Suspense reveals, which bubble up to here as an update and
          would otherwise cross-fade the whole page every time a skeleton
          resolves.
        */}
        <ViewTransition
          default={{
            forward: 'vt-page-forward',
            back: 'vt-page-back',
            default: 'none',
          }}
        >
          {children}
        </ViewTransition>
      </body>
    </html>
  )
}

