import { ViewTransition } from 'react'
import Link from 'next/link'
import { products } from '@/lib/products'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
          transitionTypes={['forward']}
        >
          {/*
            Paired with the hero on the detail page by `name`, so the two
            snapshots become one morphing group.

            `enter`/`exit` are "none" so the name is only active when a match
            exists: the three thumbnails with no counterpart keep no
            view-transition-name of their own and stay part of the page snapshot,
            sliding out with everything else instead of animating separately.
          */}
          <ViewTransition
            name={`product-image-${product.slug}`}
            share="vt-morph-image"
            enter="none"
            exit="none"
          >
            <div
              className="product-image"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}

