/* ─────────────────────────────── View transitions ───────────────────────────
   Classes here are assigned by <ViewTransition> in the components via its
   `default` / `share` / `update` props, which set `view-transition-class` on the
   captured element. Custom properties on :root inherit into the
   ::view-transition pseudo tree.
   ────────────────────────────────────────────────────────────────────────── */

:root {
  --vt-page-duration: 300ms;
  --vt-morph-duration: 420ms;
  --vt-reveal-duration: 280ms;
  --vt-ease: cubic-bezier(0.4, 0, 0.2, 1);
  --vt-page-shift: 48px;
}

/* Directional page slide: outgoing content leaves toward the edge the incoming
   content came from. */
@keyframes vt-slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(calc(-1 * var(--vt-page-shift)));
  }
}

@keyframes vt-slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(var(--vt-page-shift));
  }
}

@keyframes vt-slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(var(--vt-page-shift));
  }
}

@keyframes vt-slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(calc(-1 * var(--vt-page-shift)));
  }
}

::view-transition-group(.vt-page-forward),
::view-transition-group(.vt-page-back) {
  animation-duration: var(--vt-page-duration);
  animation-timing-function: var(--vt-ease);
}

::view-transition-old(.vt-page-forward) {
  animation: vt-slide-out-to-left var(--vt-page-duration) var(--vt-ease) both;
}

::view-transition-new(.vt-page-forward) {
  animation: vt-slide-in-from-right var(--vt-page-duration) var(--vt-ease) both;
}

::view-transition-old(.vt-page-back) {
  animation: vt-slide-out-to-right var(--vt-page-duration) var(--vt-ease) both;
}

::view-transition-new(.vt-page-back) {
  animation: vt-slide-in-from-left var(--vt-page-duration) var(--vt-ease) both;
}

/* Shared element: thumbnail ↔ hero. The group animates the geometry; the two
   snapshots are the same colour, so the cross-fade between them is invisible and
   what reads is a pure morph. Stays above the sliding page. */
::view-transition-group(.vt-morph-image) {
  animation-duration: var(--vt-morph-duration);
  animation-timing-function: var(--vt-ease);
  z-index: 2;
}

::view-transition-old(.vt-morph-image),
::view-transition-new(.vt-morph-image) {
  /* Fill the morphing box instead of letterboxing while the aspect ratio goes
     from 4/3 to 1/1 (the default is width: 100%, height: auto). */
  height: 100%;
  object-fit: fill;
  animation-duration: var(--vt-morph-duration);
  animation-timing-function: var(--vt-ease);
}

/* Suspense reveal: skeleton fades out early, content fades up into its place
   while the group eases between the two heights. */
@keyframes vt-reveal-out {
  to {
    opacity: 0;
  }
}

@keyframes vt-reveal-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

::view-transition-group(.vt-reveal) {
  animation-duration: var(--vt-reveal-duration);
  animation-timing-function: var(--vt-ease);
}

::view-transition-old(.vt-reveal) {
  animation: vt-reveal-out calc(var(--vt-reveal-duration) * 0.6) var(--vt-ease)
    both;
}

::view-transition-new(.vt-reveal) {
  animation: vt-reveal-in var(--vt-reveal-duration) var(--vt-ease) both;
}

@media (prefers-reduced-motion: reduce) {
  /* Cancelling the animations on every part of the pseudo tree cuts straight to
     the new state: the transition has nothing to wait for and finishes on the
     next frame. This has to override the user agent's own cross-fade and scale
     animations, not just the ones declared above — hence the wildcards and
     !important. */
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

